-- Seed data for local dev / initial deploy. Re-run safe (upserts on conflict).
--
-- IMPORTANT: replace the stripe_price_id placeholders below with the real
-- Price IDs from your Stripe Dashboard (Products) before going live — see
-- docs/ENV_VARS.md. The image/text credit quantities in plan_limits are
-- explicit placeholders per the brief ("definir número após medir custo real
-- de API"); tune them after measuring actual OpenAI cost per generation.
-- video_credits_per_cycle is NOT a placeholder — it's credits-as-seconds
-- (1 credit = 1 second of Runway gen4.5 output, billed at $0.12/sec), sized
-- to keep video cost under ~15-20% of each plan's monthly price. Starter
-- gets none, matching the existing no-watermark/no-seasonal-templates
-- gating pattern for premium features.
--
-- Two tiers, not three (0029_merge_creator_into_pro.sql merged the former
-- middle "Creator" tier into "Pro" on a live database — this seed reflects
-- that same end state for fresh installs). "Pro" also has an annual billing
-- option ($22/mo, billed ~$264/year) configured entirely on the payment
-- processor's side — it sends the same plan_code, so no extra row here.

  code, display_name, stripe_price_id, monthly_price_usd, is_team_plan, sort_order,
  hotmart_checkout_url, hotmart_offer_code, hotmart_checkout_url_annual, hotmart_offer_code_annual,
  annual_monthly_equivalent_usd
)
values
  ('starter', 'Starter', 'price_starter_REPLACE_ME', 19.90, false, 1,
    'https://pay.hotmart.com/R107627031E?off=z7asq0l3&checkoutMode=10', 'z7asq0l3', null, null, null),
  ('church_pro', 'Pro', 'price_church_pro_REPLACE_ME', 29.90, true, 2,
    'https://pay.hotmart.com/R107627031E?off=mx2ms7hv&checkoutMode=10', 'mx2ms7hv',
    'https://pay.hotmart.com/R107627031E?off=6z7z0oxh&checkoutMode=10', '6z7z0oxh', 22.00)
on conflict (code) do update set
  display_name = excluded.display_name,
  stripe_price_id = excluded.stripe_price_id,
  monthly_price_usd = excluded.monthly_price_usd,
  is_team_plan = excluded.is_team_plan,
  sort_order = excluded.sort_order,
  hotmart_checkout_url = excluded.hotmart_checkout_url,
  hotmart_offer_code = excluded.hotmart_offer_code,
  hotmart_checkout_url_annual = excluded.hotmart_checkout_url_annual,
  hotmart_offer_code_annual = excluded.hotmart_offer_code_annual,
  annual_monthly_equivalent_usd = excluded.annual_monthly_equivalent_usd;

  plan_code, image_credits_per_cycle, text_credits_per_cycle, video_credits_per_cycle, spiritual_chat_daily_cap,
  max_output_resolution, watermark, allow_carousel_export, allow_seasonal_templates, max_team_seats
)
values
  ('starter', 15, 30, 0, 10, 'standard', true, false, false, null),
  ('church_pro', 150, 300, 50, null, 'high', false, true, true, 10)
on conflict (plan_code) do update set
  image_credits_per_cycle = excluded.image_credits_per_cycle,
  text_credits_per_cycle = excluded.text_credits_per_cycle,
  video_credits_per_cycle = excluded.video_credits_per_cycle,
  spiritual_chat_daily_cap = excluded.spiritual_chat_daily_cap,
  max_output_resolution = excluded.max_output_resolution,
  watermark = excluded.watermark,
  allow_carousel_export = excluded.allow_carousel_export,
  allow_seasonal_templates = excluded.allow_seasonal_templates,
  max_team_seats = excluded.max_team_seats;

on conflict do nothing;

values (
  current_date,
  'Walking in Faith Today',
  'Sample devotional body for local development — replace with real generated/curated content. '
  || 'Trust in the Lord with all your heart, and lean not on your own understanding.',
  'Proverbs 3:5'
)
on conflict (publish_date) do nothing;

-- ============================================================
-- Bible reader module seed data
-- ============================================================

on conflict (code) do update set language = excluded.language, name = excluded.name, license = excluded.license;

on conflict (id) do update set duration_days = excluded.duration_days, sort_order = excluded.sort_order;

on conflict do nothing;

-- OT total: 929, NT total: 260, combined: 1189
on conflict (code) do update set testament = excluded.testament, sort_order = excluded.sort_order, chapter_count = excluded.chapter_count;

on conflict (plan_id, day_number) do update set readings = excluded.readings;

on conflict (plan_id, day_number) do update set readings = excluded.readings;

on conflict (plan_id, day_number) do update set readings = excluded.readings;

